package com.oracle.banking.notification.config;
import com.oracle.banking.shared.constants.SecurityConstants; import io.jsonwebtoken.*; import io.jsonwebtoken.io.Decoders; import io.jsonwebtoken.security.Keys; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.*; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Configuration public class SecurityConfiguration { @Bean SecurityFilterChain chain(HttpSecurity h,JwtFilter f)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/swagger-ui/**","/v3/api-docs/**","/actuator/health").permitAll().anyRequest().authenticated()).exceptionHandling(e->e.authenticationEntryPoint((q,r,x)->r.sendError(401))).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();} @Component static class JwtFilter extends OncePerRequestFilter {private final SecretKey key;JwtFilter(@Value("${security.jwt.secret}") String s){key=Keys.hmacShaKeyFor(Decoders.BASE64.decode(s));} protected void doFilterInternal(HttpServletRequest q,HttpServletResponse r,FilterChain c)throws ServletException,IOException{String h=q.getHeader("Authorization");if(h!=null&&h.startsWith(SecurityConstants.BEARER_PREFIX)){try{Claims x=Jwts.parser().verifyWith(key).build().parseSignedClaims(h.substring(7)).getPayload();List<String> roles=x.get("roles",List.class);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(x.get("username",String.class),null,roles.stream().map(v->new SimpleGrantedAuthority("ROLE_"+v)).toList()));}catch(Exception e){SecurityContextHolder.clearContext();}}c.doFilter(q,r);}}}
